from AlgorithmImports import *
from collections import deque
import math


class ParallelSpyAaplStrategy(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        self.symbols = {}
        for ticker in ["SPY", "AAPL", "IBM", "BAC", "AIG"]:
            self.symbols[ticker] = self.AddEquity(ticker, Resolution.Daily).Symbol

        self.spy = self.symbols["SPY"]
        self.aapl = self.symbols["AAPL"]

        self.closes = {ticker: deque(maxlen=101) for ticker in self.symbols}
        self.previous_closes = {ticker: None for ticker in self.symbols}

        self.aapl_red_streak = 0
        self.aapl_rsi_changes = 0
        self.aapl_gain_sum = 0.0
        self.aapl_loss_sum = 0.0
        self.aapl_average_gain = None
        self.aapl_average_loss = None
        self.aapl_rsi = None

        self.strategy_a_lot = 0
        self.strategy_b_lot = 0

    def OnData(self, data):
        # Keep market-state calculations current for every bar that is present.
        for ticker, symbol in self.symbols.items():
            if not data.Bars.ContainsKey(symbol):
                continue

            close = float(data.Bars[symbol].Close)
            prior_close = self.previous_closes[ticker]

            if ticker == "AAPL" and prior_close is not None:
                if close < prior_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0

                change = close - prior_close
                gain = max(change, 0.0)
                loss = max(-change, 0.0)
                self.aapl_rsi_changes += 1

                if self.aapl_rsi_changes <= 14:
                    self.aapl_gain_sum += gain
                    self.aapl_loss_sum += loss

                    if self.aapl_rsi_changes == 14:
                        self.aapl_average_gain = self.aapl_gain_sum / 14.0
                        self.aapl_average_loss = self.aapl_loss_sum / 14.0
                        self.aapl_rsi = self.CalculateRsi(
                            self.aapl_average_gain,
                            self.aapl_average_loss
                        )
                else:
                    self.aapl_average_gain = (
                        (self.aapl_average_gain * 13.0) + gain
                    ) / 14.0
                    self.aapl_average_loss = (
                        (self.aapl_average_loss * 13.0) + loss
                    ) / 14.0
                    self.aapl_rsi = self.CalculateRsi(
                        self.aapl_average_gain,
                        self.aapl_average_loss
                    )

            self.closes[ticker].append(close)
            self.previous_closes[ticker] = close

        # A rule day requires a bar for every subscribed ticker.
        if not all(data.Bars.ContainsKey(symbol) for symbol in self.symbols.values()):
            return

        # Do not trade until every required rolling calculation is fully formed.
        if len(self.closes["SPY"]) < 101 or self.aapl_rsi is None:
            return

        spy_close = float(data.Bars[self.spy].Close)
        aapl_close = float(data.Bars[self.aapl].Close)

        spy_history = list(self.closes["SPY"])
        spy_sma_today = sum(spy_history[-100:]) / 100.0
        spy_sma_yesterday = sum(spy_history[:-1]) / 100.0
        spy_close_yesterday = spy_history[-2]

        spy_crosses_above = (
            spy_close_yesterday <= spy_sma_yesterday and
            spy_close > spy_sma_today
        )
        spy_crosses_below = (
            spy_close_yesterday >= spy_sma_yesterday and
            spy_close < spy_sma_today
        )

        # Evaluate all sells before any buys.
        if self.strategy_a_lot > 0 and spy_crosses_below:
            self.MarketOrder(self.spy, -self.strategy_a_lot)
            self.strategy_a_lot = 0

        if self.strategy_b_lot > 0 and self.aapl_rsi > 60:
            self.MarketOrder(self.aapl, -self.strategy_b_lot)
            self.strategy_b_lot = 0

        if self.strategy_a_lot == 0 and spy_crosses_above:
            shares = int(math.floor(
                (self.Portfolio.TotalPortfolioValue * 0.40) / spy_close
            ))
            if shares > 0:
                self.MarketOrder(self.spy, shares)
                self.strategy_a_lot = shares

        if self.strategy_b_lot == 0 and self.aapl_red_streak >= 3:
            if self.Portfolio.Cash >= 20000:
                shares = int(math.floor(20000.0 / aapl_close))
                if shares > 0:
                    self.MarketOrder(self.aapl, shares)
                    self.strategy_b_lot = shares

    def CalculateRsi(self, average_gain, average_loss):
        if average_loss == 0:
            return 100.0
        if average_gain == 0:
            return 0.0

        rs = average_gain / average_loss
        return 100.0 - (100.0 / (1.0 + rs))
